"use client";

import { cn } from "@/lib/utils";
import { useSimulation } from "@/components/SimulationProvider";
import {
    Award,
    Search as SearchIcon,
    Wallet,
    Plus as PlusIcon,
    Bell as BellIcon
} from "lucide-react";

export default function Header() {
    const { currentUser } = useSimulation();

    let tier = 'Bronze';
    let tierClass = 'tier-bronze';
    let tierIcon = <Award size={14} />;

    if (currentUser.sales_total >= 15000) {
        tier = 'Ouro';
        tierClass = 'tier-ouro';
        tierIcon = <Award size={14} className="text-amber-500" />;
    } else if (currentUser.sales_total >= 5000) {
        tier = 'Prata';
        tierClass = 'tier-prata';
        tierIcon = <Award size={14} className="text-slate-400" />;
    }

    const renderAvatarContent = () => {
        if (currentUser.avatar) {
            return (
                <div
                    className="size-8 rounded-full bg-slate-200 bg-cover bg-center border border-white shadow-sm flex-shrink-0"
                    style={{ backgroundImage: `url('${currentUser.avatar}')` }}
                />
            );
        }
        const initials = currentUser.name.split(' ').map(n => n[0]).join('').substring(0, 2).toUpperCase();
        return (
            <div className="size-8 bg-primary/20 rounded-full flex items-center justify-center text-primary font-bold text-[10px] border border-white shadow-sm flex-shrink-0">
                {initials}
            </div>
        );
    };

    return (
        <header className="sticky top-0 z-40 glass-header border-b border-slate-200 dark:border-slate-800 px-4 lg:px-6 py-3">
            <div className="flex items-center justify-between max-w-full mx-auto w-full gap-4">
                <div className="flex items-center gap-3 lg:gap-4 flex-1">
                    <div className="relative w-full max-w-sm hidden md:block">
                        <SearchIcon className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                        <input
                            className="w-full bg-slate-100 dark:bg-slate-800 border-none rounded-xl py-2 pl-10 pr-4 focus:ring-2 focus:ring-primary text-xs transition-all"
                            placeholder="Buscar no painel..."
                            type="text"
                        />
                    </div>
                </div>

                <div className="flex items-center gap-2 lg:gap-3">
                    {/* Tier Badge */}
                    <div className={cn("flex items-center gap-2 px-3 lg:px-4 py-1.5 rounded-xl border font-bold text-[11px] lg:text-xs transition-all duration-500", tierClass)}>
                        {tierIcon}
                        <span>{tier}</span>
                    </div>

                    {/* Sales Value Display */}
                    <div className="hidden sm:flex items-center gap-2 bg-slate-100 dark:bg-slate-800/50 text-slate-600 dark:text-slate-300 px-3 lg:px-4 py-1.5 rounded-xl border border-slate-200 dark:border-slate-800">
                        <Wallet size={14} />
                        <span className="text-[11px] lg:text-xs font-bold tracking-tight">
                            {currentUser.sales_total.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}
                        </span>
                    </div>

                    <div className="h-6 w-px bg-slate-200 dark:bg-slate-800 mx-1"></div>

                    <button className="bg-primary text-white px-4 py-2 rounded-xl font-bold text-xs flex items-center gap-2 shadow-lg shadow-primary/20 hover:scale-[1.02] transition-all">
                        <PlusIcon size={14} />
                        <span className="hidden lg:inline">Emitir</span>
                    </button>

                    <button className="size-9 flex items-center justify-center rounded-xl bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 relative hover:bg-slate-200 transition-colors">
                        <BellIcon size={20} />
                        <span className="absolute top-2.5 right-2.5 size-1.5 bg-red-500 rounded-full border border-white dark:border-slate-900"></span>
                    </button>

                    <div className="header-user-avatar">
                        {renderAvatarContent()}
                    </div>
                </div>
            </div>

            {/* Mobile Search */}
            <div className="mt-3 md:hidden relative">
                <SearchIcon className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                <input
                    className="w-full bg-slate-100 dark:bg-slate-800 border-none rounded-xl py-2 pl-10 pr-4 focus:ring-2 focus:ring-primary text-xs"
                    placeholder="Buscar..."
                    type="text"
                />
            </div>
        </header>
    );
}
