"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import {
    BarChart3,
    Campaign,
    ChevronRight,
    Close,
    Dashboard,
    Description,
    Group,
    Logout,
    Payments,
    Settings,
    ShoppingCart,
    VerifiedUser
} from "lucide-react"; // Using Lucide names or equivalents
import { cn } from "@/lib/utils";
import { useState } from "react";
import { useSimulation } from "@/components/SimulationProvider";

// Mock Lucide icons that map to Material Symbols intent
import {
    LayoutDashboard,
    FileText,
    Store,
    Megaphone,
    Users,
    DollarSign,
    BarChart,
    Settings as SettingsIcon,
    ShieldCheck,
    X,
    LogOut
} from "lucide-react";

interface NavItem {
    label: string;
    href: string;
    icon: any;
}

const navItems: NavItem[] = [
    { label: "Painel", href: "/", icon: LayoutDashboard },
    { label: "Certificados", href: "/certificados", icon: FileText },
    { label: "Links de Venda", href: "/loja", icon: Store },
    { label: "Campanhas / Cupons", href: "/campanhas", icon: Megaphone },
    { label: "Clientes", href: "/clientes", icon: Users },
    { label: "Financeiro", href: "/financeiro", icon: DollarSign },
    { label: "Relatórios", href: "/relatorios", icon: BarChart },
    { label: "Configurações", href: "/configuracoes", icon: SettingsIcon },
];

export default function Sidebar() {
    const pathname = usePathname();
    const [isOpen, setIsOpen] = useState(false);
    const { currentUser, toggleRole } = useSimulation();

    const toggleSidebar = () => setIsOpen(!isOpen);

    const renderAvatarContent = () => {
        if (currentUser.avatar) {
            return (
                <div
                    className="size-9 rounded-full bg-slate-200 bg-cover bg-center border border-white shadow-sm flex-shrink-0"
                    style={{ backgroundImage: `url('${currentUser.avatar}')` }}
                />
            );
        }
        const initials = currentUser.name.split(' ').map(n => n[0]).join('').substring(0, 2).toUpperCase();
        return (
            <div className="size-9 bg-primary/20 rounded-full flex items-center justify-center text-primary font-bold text-xs border border-white shadow-sm flex-shrink-0">
                {initials}
            </div>
        );
    };

    return (
        <>
            <aside
                className={cn(
                    "w-64 bg-navy-sidebar text-slate-300 flex flex-col fixed h-full z-50 transition-transform duration-300 lg:translate-x-0",
                    isOpen ? "translate-x-0" : "-translate-x-full"
                )}
            >
                <div className="p-6 flex items-center justify-between">
                    <div className="flex items-center gap-3">
                        <div className="size-10 bg-primary rounded-lg flex items-center justify-center text-white shadow-lg shadow-primary/20">
                            <ShieldCheck size={24} />
                        </div>
                        <div>
                            <h1 className="text-white text-base font-bold leading-none">Delta Estrategista</h1>
                            <p className="text-xs text-slate-500 mt-1">Controle de Certificados</p>
                        </div>
                    </div>
                    <button onClick={toggleSidebar} className="lg:hidden text-slate-400 hover:text-white">
                        <X size={24} />
                    </button>
                </div>

                <nav className="flex-1 px-4 py-4 space-y-1">
                    {navItems.map((item) => {
                        const isActive = pathname === item.href;
                        const Icon = item.icon;
                        return (
                            <Link
                                key={item.href}
                                href={item.href}
                                className={cn(
                                    "flex items-center gap-3 px-3 py-2.5 rounded-lg transition-all duration-200 group",
                                    isActive
                                        ? "bg-primary text-white shadow-lg shadow-primary/20"
                                        : "hover:bg-white/5 text-slate-400 hover:text-white"
                                )}
                            >
                                <Icon size={22} className={isActive ? "text-white" : "text-slate-500 group-hover:text-primary transition-colors"} />
                                <span className="text-sm font-medium">{item.label}</span>
                            </Link>
                        );
                    })}
                </nav>

                {/* Simulation Switcher (Solo para a Demo) */}
                <div className="px-4 py-2 border-t border-white/5">
                    <button
                        onClick={toggleRole}
                        className="w-full bg-white/5 hover:bg-white/10 text-[10px] text-slate-400 py-1.5 rounded-lg border border-white/10 transition-colors uppercase font-bold tracking-widest"
                    >
                        Alternar Visão (Admin / Vendedor)
                    </button>
                </div>

                <div className="p-4 border-t border-white/10 mt-auto">
                    <div className="flex items-center gap-3 px-3 py-3 bg-white/5 rounded-xl border border-white/5">
                        <div className="sidebar-user-avatar">
                            {renderAvatarContent()}
                        </div>
                        <div className="overflow-hidden">
                            <p className="text-white text-sm font-bold truncate">{currentUser.name}</p>
                            <p className="text-[10px] text-slate-500 uppercase font-bold tracking-wider">{currentUser.role === 'admin' ? 'Administrador' : 'Vendedor'}</p>
                        </div>
                    </div>
                    <button className="flex items-center gap-3 w-full px-3 py-2.5 rounded-lg hover:bg-white/5 transition-colors text-red-400 mt-2">
                        <LogOut size={22} />
                        <span className="text-sm font-medium">Sair</span>
                    </button>
                </div>
            </aside>

            {/* Mobile Toggle Trigger (Hidden on Desktop) */}
            {!isOpen && (
                <button
                    onClick={toggleSidebar}
                    className="lg:hidden fixed top-4 left-4 z-50 p-2 bg-white dark:bg-slate-800 rounded-lg shadow-md"
                >
                    <LayoutDashboard size={24} />
                </button>
            )}
        </>
    );
}
