"use client";

import React, { createContext, useContext, useState, useEffect } from "react";
import { supabase } from "@/lib/supabase";

interface UserProfile {
    id: string;
    name: string;
    company: string;
    role: "admin" | "seller";
    email: string;
    sales_total: number;
    level: "Bronze" | "Prata" | "Ouro";
    xp: number;
    wallet: number;
    equippedBadge?: string;
    salesCount60Days: number;
    avatar?: string;
    preferences?: {
        darkMode: boolean;
    };
}

interface SimulationContextType {
    currentUser: UserProfile;
    isAuthenticated: boolean;
    loading: boolean;
    toggleRole: () => void;
    updateUser: (updates: Partial<UserProfile>) => void;
    logout: () => Promise<void>;
}

const defaultUser: UserProfile = {
    id: "vend_001",
    name: "Maria Silva",
    email: "maria.silva@delta.com.br",
    company: "Contabilidade Central",
    role: "seller",
    sales_total: 8450.00,
    level: "Prata",
    xp: 1250,
    wallet: 450.00,
    equippedBadge: "Start",
    salesCount60Days: 24,
    avatar: "https://lh3.googleusercontent.com/aida-public/AB6AXuAA65jbQbRFT_PDlvYMVTP3jdi6Y0M5XKach0uVKCc-u2nNiGY4dXathU9JL2D1fYBSRDJi1KuMjH_m4OZJTcO-vfJ3w0gVvuveIyKE23dzwugAuCd7laQ0bZE2IrG5aFxSPVmApOaPv2qJGIw4iLTESk8t2EBUYQJBTjzFFqpxVPxizXpfvDG_E8MSjXrNJCg4v3hJiYh3thS6oAAbbg3lP9pJL9tg8WUQXGUnMB8Z9CS_Dx6TE6QSzjjnWEoYy5CQSiCjDAc63_M",
    preferences: { darkMode: true }
};

const SimulationContext = createContext<SimulationContextType | undefined>(undefined);

export function SimulationProvider({ children }: { children: React.ReactNode }) {
    const [currentUser, setCurrentUser] = useState<UserProfile>(defaultUser);
    const [loading, setLoading] = useState(true);
    const [isAuthenticated, setIsAuthenticated] = useState(false);

    const updateUser = (updates: Partial<UserProfile>) => {
        setCurrentUser(prev => ({ ...prev, ...updates }));
    };

    const logout = async () => {
        await supabase.auth.signOut();
        setIsAuthenticated(false);
        window.location.reload();
    };

    const toggleRole = () => {
        setCurrentUser(prev => {
            if (prev.role === "seller") {
                return {
                    id: "admin_master",
                    name: "Helio (Admin)",
                    email: "helio@delta.com.br",
                    company: "Delta Estrategista",
                    role: "admin",
                    sales_total: 25480.00,
                    level: "Ouro",
                    xp: 5000,
                    wallet: 1500.00,
                    salesCount60Days: 120,
                    avatar: undefined,
                    preferences: { darkMode: true }
                };
            } else {
                return defaultUser;
            }
        });
    };

    // Load actual profile if connected to Supabase
    useEffect(() => {
        const loadProfile = async () => {
            try {
                const { data: { session } } = await supabase.auth.getSession();

                if (session) {
                    setIsAuthenticated(true);
                    const { data: profile } = await supabase
                        .from('profiles')
                        .select('*')
                        .eq('id', session.user.id)
                        .single();

                    if (profile) {
                        setCurrentUser(prev => ({
                            ...prev,
                            id: profile.id,
                            name: profile.full_name,
                            role: profile.role,
                            level: profile.level,
                            xp: profile.xp || 0,
                            wallet: Number(profile.wallet) || 0,
                            email: profile.email
                        }));
                    }
                } else {
                    setIsAuthenticated(false);
                }
            } catch (err) {
                console.warn("Supabase profile load failed. Using simulated user.");
            } finally {
                setLoading(false);
            }
        };

        loadProfile();

        const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
            setIsAuthenticated(!!session);
            if (!session) {
                setLoading(false);
            } else {
                loadProfile();
            }
        });

        return () => subscription.unsubscribe();
    }, []);

    useEffect(() => {
        if (currentUser.preferences?.darkMode) {
            document.documentElement.classList.add("dark");
        } else {
            document.documentElement.classList.remove("dark");
        }
    }, [currentUser.preferences?.darkMode]);

    return (
        <SimulationContext.Provider value={{ currentUser, toggleRole, updateUser, isAuthenticated, loading, logout }}>
            {children}
        </SimulationContext.Provider>
    );
}

export function useSimulation() {
    const context = useContext(SimulationContext);
    if (context === undefined) {
        throw new Error("useSimulation must be used within a SimulationProvider");
    }
    return context;
}
